25	async function startServer(args, { cwd } = {}) {
26	  const child = spawn(process.execPath, [CLI, 'serve', ...args], { cwd, stdio: ['ignore', 'pipe', 'pipe'] });
27	  let stdout = '';
28	  let stderr = '';
29	  child.stdout.on('data', (chunk) => { stdout += chunk; });
30	  child.stderr.on('data', (chunk) => { stderr += chunk; });
31	  const address = await new Promise((resolve, reject) => {
32	    child.stdout.on('data', () => {
33	      const index = stdout.indexOf('\n');
34	      if (index === -1) return;
35	      try {
36	        resolve(JSON.parse(stdout.slice(0, index)));
37	      } catch (error) {
38	        reject(error);
39	      }
40	    });
41	    child.on('exit', (code) => reject(new Error(`server exited with status ${code}: ${stderr.trim()}`)));
42	  });
43	  return {
44	    child,
45	    address,
46	    url: `http://${address.host}:${address.port}`,
47	    stop: () => new Promise((resolve) => {
48	      child.once('exit', resolve);
49	      child.kill('SIGKILL');
50	    }),
51	  };
52	}
