  const incoming = normalizeSnapshot(incomingData);

  const current = this.#documents;
  const baseMap = new Map(base.map((d) => [d.id, d]));
  const incomingMap = new Map(incoming.map((d) => [d.id, d]));
  const next = new Map();
  const conflicts = [];

  const allIds = new Set([...baseMap.keys(), ...incomingMap.keys(), ...current.keys()]);

  for (const id of allIds) {
    const b = baseMap.get(id);
    const i = incomingMap.get(id);
    const c = current.get(id);

    if (b && i && c) {
      // Three-way field merge.
      const result = { id, title: c.title, body: c.body, tags: [...c.tags] };
      const fields = new Set();
      for (const field of ['title', 'body', 'tags']) {
        const bVal = field === 'tags' ? b.tags : b[field];
        const iVal = field === 'tags' ? i.tags : i[field];
        const cVal = field === 'tags' ? c.tags : c[field];
        if (!fieldEqual(bVal, iVal)) {
          // Offline changed this field.
          if (fieldEqual(cVal, bVal)) {
            // Online unchanged: take offline's value.
            result[field] = field === 'tags' ? [...iVal] : iVal;
          } else if (fieldEqual(cVal, iVal)) {
            // Both changed to the same value: keep.
