node -e "
import('./src/workspace.js').then(({ Workspace }) => {
  // Quick smoke test: basic 3-way merge
  const ws = new Workspace();
  ws.add({ id: 'a', title: 'Alpha', body: 'original', tags: ['one'] });

  const base = ws.exportJSON();

  // Online: change body
  ws.remove('a');
  ws.add({ id: 'a', title: 'Alpha', body: 'online body', tags: ['one'] });

  // Offline: change title
  const incoming = (() => {
    const w = new Workspace();
    w.add({ id: 'a', title: 'Alpha v2', body: 'original', tags: ['one'] });
    return w.exportJSON();
  })();

  const result = ws.reconcile(base, incoming);
  const doc = result.documents.find(d => d.id === 'a');
  console.log('title:', doc.title, '(expected Alpha v2)');
  console.log('body:', doc.body, '(expected online body)');
  console.log('tags:', JSON.stringify(doc.tags), '(expected [\"one\"])');
  console.log('checksum:', result.checksum === ws.exportJSON().checksum ? 'matches current' : 'differs');
});
"

