import('./src/workspace.js').then(({ Workspace, SnapshotError }) => {
  // Test 1: field conflict
  const ws = new Workspace();
  ws.add({ id: 'a', title: 'T', body: 'B', tags: ['x'] });
  const base = ws.exportJSON();

  // Online: change title
  ws.remove('a');
  ws.add({ id: 'a', title: 'online', body: 'B', tags: ['x'] });

  // Offline: change title differently
  const incoming = (() => {
    const w = new Workspace();
    w.add({ id: 'a', title: 'offline', body: 'B', tags: ['x'] });
    return w.exportJSON();
  })();

  try {
    ws.reconcile(base, incoming);
    console.log('FAIL: should have thrown');
  } catch (e) {
    console.log('conflict code:', e.code, '(expected RECONCILE_CONFLICT)');
    console.log('conflicts:', JSON.stringify(e.conflicts), '(expected [{\"id\":\"a\",\"fields\":[\"title\"]}])');
  }

  // Test 2: no-op (base == incoming)
  const ws2 = new Workspace();
  ws2.add({ id: 'a', title: 'A', body: 'b', tags: [] });
  const base2 = ws2.exportJSON();
  const result2 = ws2.reconcile(base2, base2);
  console.log('no-op checksum match:', result2.checksum === ws2.exportJSON().checksum, '(expected true)');

  // Test 3: dryRun doesn't modify
  const ws3 = new Workspace();
  ws3.add({ id: 'a', title: 'A', body: 'b', tags: [] });
  const base3 = ws3.exportJSON();
  const incoming3 = (() => {
    const w = new Workspace();
    w.add({ id: 'a', title: 'A2', body: 'b', tags: [] });
    return w.exportJSON();
  })();
  const before = ws3.exportJSON().checksum;
  ws3.reconcile(base3, incoming3, { dryRun: true });
  console.log('dryRun unchanged:', ws3.exportJSON().checksum === before, '(expected true)');
});
"
